using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
namespace Xinghai.MapEditor.Editor {public static class ScaleProof {
 static string Key(Quad q){return string.Join(",",new[]{q.axis,q.sign,q.plane,q.a,q.b,q.w,q.h,q.color})+":"+q.chunk;}
 public static void Run(){try{foreach(var item in JArray.Parse(File.ReadAllText("../scale/golden.json"))){var doc=SourceReader.Parse(item["doc"].ToString());var actual=GreedyMesher.Build(doc).Select(Key).OrderBy(x=>x).ToArray();var expected=item["faces"].ToObject<Quad[]>().Select(Key).OrderBy(x=>x).ToArray();if(!actual.SequenceEqual(expected))throw new Exception("Cross-engine face/color mismatch "+doc.mapId);}
 var rows=new List<object>();foreach(var name in new[]{"small","medium","large"}){var doc=SourceReader.Parse(File.ReadAllText("../scale/"+name+".json"));doc.revision=Environment.TickCount&int.MaxValue;var timer=System.Diagnostics.Stopwatch.StartNew();var prefab=MapBaker.Bake(doc,"Assets/Generated/"+doc.mapId);rows.Add(new{name,milliseconds=timer.ElapsedMilliseconds,cells=doc.cells.Length,vertices=prefab.GetComponentsInChildren<MeshFilter>().Sum(m=>m.sharedMesh.vertexCount),triangles=prefab.GetComponentsInChildren<MeshFilter>().Sum(m=>m.sharedMesh.triangles.Length/3),chunks=prefab.GetComponentsInChildren<MeshCollider>().Length,memoryMiB=GC.GetTotalMemory(true)/1048576});}
 var go=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Fixtures/direction.fbx");var bounds=new Bounds();bool first=true;foreach(var r in go.GetComponentsInChildren<Renderer>()){if(first){bounds=r.bounds;first=false;}else bounds.Encapsulate(r.bounds);}File.WriteAllText("../logs/scale-tuanjie.json",JsonConvert.SerializeObject(new{passed=true,goldenCases=8,version=Application.unityVersion,pipeline="Built-in",modelBounds=new{center=new[]{bounds.center.x,bounds.center.y,bounds.center.z},size=new[]{bounds.size.x,bounds.size.y,bounds.size.z}},results=rows},Formatting.Indented));Debug.Log("XH_SCALE_PASS");EditorApplication.Exit(0);
 }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}}
